export function translate(language: string, text: string): string {
  if (language === 'English') return text;
  const selectedLanguage = language as Exclude<UiLanguage, 'English'>;
  return screenTranslations[selectedLanguage]?.[text] ?? translations[selectedLanguage]?.[text] ?? text;
}
